/**
 * The combined `index.ts` barrel has to survive two barrels exporting one name.
 *
 * It re-exports `functions`, `models`, `jobs` and `controllers` with
 * `export *`, and a name two of them share is ambiguous: TypeScript drops it
 * and reports TS2308 on `index.ts`. The framework's own defaults do this -
 * `functions/mail-preferences` exports a `MailPreference` type beside the
 * `MailPreference` model - so every app's `typecheck` failed until the
 * generated file was patched by hand, and the next generation wiped the patch.
 */

import { mkdtempSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import { afterAll, describe, expect, it } from 'bun:test'
import { barrelExportNames, combinedBarrel } from '../src/imports'

const functions = [
  '// Generated by bun-plugin-auto-imports',
  `export { fetchMailPreference, saveMailPreference } from './fns/mail-preferences'`,
  `export type { MailTheme, MailPreference } from './fns/mail-preferences'`,
  `export type { Release, ReleaseStats } from './fns/releases'`,
].join('\n')

const models = [
  '// Generated by bun-plugin-auto-imports',
  `export { default as MailPreference } from './models/MailPreference'`,
  `export { default as Release } from './models/Release'`,
  `export { default as User } from './models/User'`,
  `// Skipped 'Map' - would shadow a built-in global. Import directly if needed.`,
  `// export { default as Map } from './models/Map'`,
].join('\n')

describe('barrelExportNames', () => {
  it('reads value, type and aliased exports, and skips commented-out ones', () => {
    const names = barrelExportNames(`${functions}\n${models}\nexport { a as b, type C } from './x'`)

    expect(names.get('fetchMailPreference')).toEqual({ typeOnly: false })
    expect(names.get('MailTheme')).toEqual({ typeOnly: true })
    expect(names.get('User')).toEqual({ typeOnly: false })
    expect(names.get('b')).toEqual({ typeOnly: false })
    expect(names.get('C')).toEqual({ typeOnly: true })
    expect(names.has('a')).toBe(false)
    expect(names.has('Map')).toBe(false)
  })
})

describe('combinedBarrel', () => {
  it('is only the star exports when no name is shared', () => {
    expect(combinedBarrel([
      { name: 'functions', source: `export { useThing } from './a'` },
      { name: 'models', source: `export { default as User } from './User'` },
    ])).toBe([
      '// Generated by bun-plugin-auto-imports',
      `export * from './functions'`,
      `export * from './models'`,
      '',
    ].join('\n'))
  })

  it('re-exports a shared name from the later barrel, so models beat functions', () => {
    const barrel = combinedBarrel([
      { name: 'functions', source: functions },
      { name: 'models', source: models },
      { name: 'jobs', source: '' },
      { name: 'controllers', source: '' },
    ])

    expect(barrel).toContain(`export { MailPreference, Release } from './models'`)
    expect(barrel).not.toMatch(/\} from '\.\/functions'/)
    expect(barrel).not.toContain('User }')
  })

  it('keeps a type-only winner a type re-export', () => {
    const barrel = combinedBarrel([
      { name: 'functions', source: `export { Shape } from './a'` },
      { name: 'models', source: `export type { Shape } from './b'` },
    ])

    expect(barrel).toContain(`export type { Shape } from './models'`)
  })

  describe('compiles', () => {
    const dir = mkdtempSync(join(tmpdir(), 'stacks-combined-barrel-'))
    afterAll(() => rmSync(dir, { recursive: true, force: true }))

    it('with a type in functions and a model in models sharing a name', async () => {
      writeFileSync(join(dir, 'functions.ts'), [
        'export interface MailPreference { theme: string }',
        'export function fetchMailPreference(): MailPreference { return { theme: \'dark\' } }',
      ].join('\n'))
      writeFileSync(join(dir, 'models.ts'), 'export class MailPreference { id = 1 }\nexport class User {}\n')
      writeFileSync(join(dir, 'jobs.ts'), 'export {}\n')
      writeFileSync(join(dir, 'controllers.ts'), 'export {}\n')
      writeFileSync(join(dir, 'index.ts'), combinedBarrel([
        { name: 'functions', source: `export type { MailPreference } from './fns'\nexport { fetchMailPreference } from './fns'` },
        { name: 'models', source: `export { default as MailPreference } from './MailPreference'\nexport { default as User } from './User'` },
        { name: 'jobs', source: '' },
        { name: 'controllers', source: '' },
      ]))
      writeFileSync(join(dir, 'use.ts'), [
        `import { MailPreference, User, fetchMailPreference } from './index'`,
        'export const id: number = new MailPreference().id',
        'export const user = new User()',
        'export const pref = fetchMailPreference()',
      ].join('\n'))

      const tsc = Bun.spawnSync([process.execPath, require.resolve('typescript/lib/tsc.js'), '--noEmit', '--strict', '--isolatedModules', '--module', 'esnext', '--moduleResolution', 'bundler', '--target', 'esnext', join(dir, 'use.ts')], {
        cwd: dir,
        stdout: 'pipe',
        stderr: 'pipe',
      })

      expect(`${tsc.stdout.toString()}${tsc.stderr.toString()}`).toBe('')
      expect(tsc.exitCode).toBe(0)
    }, 60_000)
  })
})
